-- DarkChaos: map 751 drop ladder (and map 750's upper Hyjal band) on the continued item curve
--
-- Measured 11-11: map 751 creatures dropped NO gear for their level - 2,785 vanilla items (average item level
-- 44.6, nothing above RequiredLevel 106) through stock references - and only 536 of its 1,358 combat creature
-- types had loot at all. Quest rewards were the only band gear. Map 750 got the same kind of ladder in 337_.
--
-- This is 337_'s recipe on the item curve approved 11-11 (green T(L) = 388 + 2.5*(L-113) up to 130 = 430, then
-- 430 + 3*(L-130) up to 160 = 520; blue +8):
--   band   121  130  134  138  142  145  148  152  156
--   green  408  430  442  454  466  475  484  496  508      RequiredLevel = band
-- Each band: green + blue for 8 slots x cloth/leather/mail/plate, a shield, neck/back/ring/trinket and six weapon
-- types = 86 items; 774 in all, 421000-421773. Stats are 337_'s: budget 0.00207 * ilvl^2.13 * slot
-- weight * quality (0.85 green, 1.0 blue) split 32/28/23/17 over 319_'s archetypes; looks are borrowed from
-- existing items of the same class/subclass/slot (the ranks after the ten 337_ used, so no look repeats in a
-- slot). Unlike 337_, armor and weapon damage are set, from the Cata curve DBCs at the item level.
--
-- Loot: one reference per band (752210-752218), one group, greens weight 100 / blues 25 - 337_'s layout. A
-- creature rolls it by rank: normal 1.2%, elite 6%, rare 20%, rare elite 35%, boss 60% (337_). Band = the
-- highest band at or below the creature's level.
--   map 751: 758 combat creature types spawned only there, level 125+, the same filters as 332_. Those
--     with their own loot (536) get one more row; 222 plain combat mobs that had NO
--     loot get lootid = entry. Vendors, quest givers and other service NPCs without loot stay without.
--   map 750: the 33 Hyjal creatures of level 121-130 move from 337_'s 113 reference (752204) to band 121.
--
-- 🔴 The items are discarded at load unless Item.dbc has their rows (server AND clients). Those rows are deployed
-- separately (Custom/CSV DBC/Item.csv -> Item.dbc). Apply to acore_world, then restart the worldserver.
--
-- Uninstall: the DELETEs in steps 2 and 5, `DELETE FROM item_template WHERE entry BETWEEN 421000 AND 421999`,
-- `UPDATE creature_template SET lootid = 0` for the
-- entries in dc_ladder_751_lootid, plus re-adding 752204 for the 750 movers (entries in dc_ladder_750_move).

-- 1. the items (item_template rows are never deleted - codestyle - so this is a REPLACE)
